task_names={'chat':'Чат','intake':'Потребность','search':'Поиск','analysis':'Бизнес','strategy':'Стратегия','review':'Документы','draft':'Черновик','changes':'Изменения','workspace':'Разделы'}
for idx,profile in enumerate(['incomplete','company','project']):
    if idx:page('Реальный ИИ для '+('компании' if profile=='company' else 'проекта'))
    doc.add_heading({'incomplete':'Неполный профиль','company':'Профиль компании','project':'Проект без компании'}[profile],2)
    rows=[]
    for c in repeat['cases']:
        if c.get('profile')!=profile or c['id'] not in {f'LIVE-{profile}-{t}' for t in task_names}:continue
        old=next(x for x in first['cases'] if x['id']==c['id'])
        reason='; '.join(c.get('failedChecks',[])) or 'Критерии выполнены'
        failure=c.get('providerFailure')
        if failure:reason=str(failure)+'; '+reason
        rows.append([task_names[c['task']], 'Да' if old['status']=='pass' else 'Нет','Да' if c['status']=='pass' else 'Нет',round(c.get('durationMs',0)/1000,1),reason])
    table(['Задача','До','После','Сек','Проверенный результат'],rows,[1.05,.45,.6,.5,4.5])
    p('«Да» означает прохождение технических критериев конкретного запроса. «Нет» означает, что ожидаемый AI-результат не получен. Полные ответы, failedChecks и сведения провайдера сохранены в live-first.json и live-repeat.json. Профили и документы синтетические.')
    if profile=='company':p('Сценарии review, draft и workspace требуют структурированного ответа. Для них добавлена проверка JSON и одна попытка исправить формат. Диалоговые задачи получают обычный текст; к ним не применяется схема замечаний к документу.')
    if profile=='project':p('Рекомендация для проекта не подтверждает право на меру для зарегистрированного юридического лица. Серверные правила отдельно проверяют допустимый тип заявителя; модель не может создавать собственные идентификаторы программ.')

